            if (kind == Model.nkSection()) {
                emon.Port.textCp(t, 83);
                emon.Port.textI32(t, Model.nodeSub(nodes, i));
            }
            if (kind == Model.nkHeading()) {
                emon.Port.textCp(t, 72);
                emon.Port.textI32(t, Model.nodeSub(nodes, i));
                emon.Port.textCp(t, 58);
                s = Model.nodeTextStart(nodes, i);
                k = 0;
                while (k < Model.nodeTextLen(nodes, i)) {
                    emon.Port.textCp(t, Model.textAt(text, s + k));
                    k += 1;
                }
            }
            if (kind == Model.nkParagraph()) {
                emon.Port.textCp(t, 80);
            }
            if (kind == Model.nkBreak()) {
                emon.Port.textCp(t, 66);
                emon.Port.textI32(t, Model.nodeSub(nodes, i));
            }
            emon.Port.textCp(t, 59);
            i += 1;
