    public static void testAnOutlineOverrulesTheSequence() {
        emon.Port.Cells wd = emon.Port.newCells();
        emon.Port.Cells ln = emon.Port.newCells();
        emon.Port.Cells et = emon.Port.newCells();
        emon.Port.Cells sf = emon.Port.newCells();
        emon.Port.Cells sc = emon.Port.newCells();
        emon.Port.Cells hc = emon.Port.newCells();
        emon.Port.Cells ws = emon.Port.newCells();
        emon.Port.Cells tmp = emon.Port.newCells();
        emon.Port.Cells pr = emon.Port.newCells();
        emon.Port.Cells ptxt = emon.Port.newCells();
        emon.Port.Cells ttl = emon.Port.newCells();
        int y = 5000;
        // Alpha (12 pt bold) comes first, Beta (16 pt bold) after: the sequence says Alpha is the parent
        htHeading(wd, ln, et, emon.Testport.textBlob("Alpha"), y, 1200, 1);
        y += 2300;
        y = htBody(wd, ln, et, 1, y, 2);
        y += 900;
        htHeading(wd, ln, et, emon.Testport.textBlob("Beta"), y, 1600, 1);
        y += 2500;
        y = htBody(wd, ln, et, 1, y, 2);
        y += 900;
        htHeading(wd, ln, et, emon.Testport.textBlob("Alpha"), y, 1200, 1);
        y += 2300;
        y = htBody(wd, ln, et, 1, y, 2);
        y += 900;
        htHeading(wd, ln, et, emon.Testport.textBlob("Beta"), y, 1600, 1);
        y += 2500;
        y = htBody(wd, ln, et, 1, y, 2);
        emon.Testport.assertEq(htRun(wd, ln, et, sf, sc, hc, ws, tmp, pr, ptxt), 4, "four headings");
        emon.Testport.assertEq(Heading.hdLevel(hc, 0), 1, "without a prior the first class is the top");
        emon.Testport.assertEq(Heading.hdLevel(hc, 3), 2, "and the other under it");
        // an outline says Beta is at depth 0 and Alpha at depth 1
        Model.textAppendUtf8(ttl, emon.Testport.textBlob("Beta"), 0, 4);
        Heading.hdPriorAdd(pr, ptxt, 2, 0, 4, ttl, 1, 800);
        Model.textAppendUtf8(ttl, emon.Testport.textBlob("Alpha"), 0, 5);
        Heading.hdPriorAdd(pr, ptxt, 2, 4, 5, ttl, 2, 800);
        emon.Testport.assertEq(htRun(wd, ln, et, sf, sc, hc, ws, tmp, pr, ptxt), 4, "four headings");
        emon.Testport.assertEq(Heading.hdLevel(hc, 0), 2, "now Alpha is the inner heading");
        emon.Testport.assertEq(Heading.hdLevel(hc, 3), 1, "and Beta the outer, as the author's outline says");
    }
    public static void testAnOutlineRowIsAPrior() {
        emon.Port.Cells ol = emon.Port.newCells();
        emon.Port.Cells txt = emon.Port.newCells();
        emon.Port.Cells pr = emon.Port.newCells();
        emon.Port.Cells ptxt = emon.Port.newCells();
        int i = 0;
        while (i < 24) {
            emon.Port.cellsPush(ol, 0);
            i += 1;
        }
        Model.textAppendUtf8(txt, emon.Testport.textBlob("xxIntroduction"), 0, 14);
        emon.Port.cellsSet(ol, 0, 2);
        emon.Port.cellsSet(ol, 5, 2);
        emon.Port.cellsSet(ol, 6, 12);
        emon.Testport.assertEq(Heading.hdPriorOutline(ol, txt, pr, ptxt), 1, "one row read");
        emon.Testport.assertEq(emon.Port.cellsAt(pr, 1), 12, "its title is twelve code points");
        emon.Testport.assertEq(emon.Port.cellsAt(pr, 2), 3, "at depth 2, so level 3");
        emon.Testport.assertEq(emon.Port.cellsAt(pr, 3), 2, "from an outline");
        emon.Testport.assertEq(emon.Port.cellsAt(pr, 4), 800, "with the weight of a healthy outline");
        emon.Testport.assertEq(emon.Port.cellsLen(ptxt), 12, "and its text copied");
    }
    public static int htGolden(byte[] pdf, StringBuilder t, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells cx, emon.Port.Cells ox, emon.Port.Cells cs, emon.Port.Cells out, emon.Port.Cells f0, emon.Port.Cells f1, emon.Port.Cells f2, emon.Port.Cells f3, emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells mk, emon.Port.Cells fnt, emon.Port.Cells pg, emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells pages, emon.Port.Cells ledger, emon.Port.Cells layout, emon.Port.Cells ord, emon.Port.Cells raw, emon.Port.Cells tmp, emon.Port.Cells fr, emon.Port.Cells gp, emon.Port.Cells mst, emon.Port.Cells sf, emon.Port.Cells sc, emon.Port.Cells hc, emon.Port.Cells ws, emon.Port.Cells tmp2, emon.Port.Cells pr, emon.Port.Cells ptxt) {
        // PDF -> content -> headings -> paragraphs and sections -> Model -> pretty JSON; answer 0 when every step
        // answered 0, else a code naming the step (1 open, 2 content, 3 the Model's check). The JSON is `t`.
        emon.Port.cellsDrop(gl, 0);
        emon.Port.cellsDrop(et, 0);
        emon.Port.cellsDrop(mk, 0);
        emon.Port.cellsDrop(fnt, 0);
        emon.Port.cellsDrop(wd, 0);
        emon.Port.cellsDrop(ln, 0);
        emon.Port.Src src = emon.Port.srcOfBlob(pdf);
        emon.Port.Cells pa = emon.Port.newCells();
        emon.Port.Cells im = emon.Port.newCells();
        emon.Port.Cells pts = emon.Port.newCells();
        emon.Port.Cells gx = emon.Port.newCells();
        int o = Pdfdoc.pdOpen(src, ar, dc, a, b, st);
        if (o != 0) {
            return 1;
        }
        if (Pdfcontent.pcDocument(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln, pa, im, pts, gx) != 0) {
            return 2;
        }
        Heading.hdAnalyze(wd, ln, et, gl, sf, sc, hc, ws, tmp2, pr, ptxt);
        Model.modelInit(nodes, attrs, regions, text, pages, ledger, layout);
        Para.paPages(pg, pages);
        int np = emon.Port.cellsLen(pages) / 16;
        htPa(wd, ln, et, np, pages, layout, nodes, attrs, regions, text, ord, raw, tmp, fr, gp, hc);
        if (Model.modelCheck(nodes, attrs, regions, text, pages, ledger, layout, mst) != 0) {
            return 3;
        }
        Json.jsEmit(t, 1, nodes, attrs, regions, text, pages, ledger, layout, layout, layout);
        return 0;
    }
